import java.nio.file.Files;
import java.nio.file.Path;

public final class RolesTest {
    public static void main(String[] args) throws Exception {
        String data = Files.readString(Path.of("allowed_roles.txt")).trim();
        for (String role : data.split(",")) {
            role = role.trim();
            if (!Roles.isAllowed(role)) throw new AssertionError("isAllowed(" + role + ") should be true");
        }
        if (Roles.isAllowed("not_a_real_role")) throw new AssertionError("isAllowed should reject an unknown role");
        System.out.println("all tests passed");
    }
}

