import java.nio.file.Files;
import java.nio.file.Path;

public final class Roles {
    public static boolean isAllowed(String role) throws Exception {
        String data = Files.readString(Path.of("allowed_roles.txt")).trim();
        for (String r : data.split(",")) {
            if (r.trim().equals(role)) return true;
        }
        return false;
    }
}

